create table if not exists public.conik_subscriptions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,plan_code text not null check(plan_code in('basic','premium')),duration_days integer not null default 30 check(duration_days=30),amount numeric(12,2) not null default 0 check(amount>=0),currency text not null default 'XOF',starts_at timestamptz not null default now(),ends_at timestamptz not null,status text not null default 'active' check(status in('pending','active','expired','cancelled')),payment_id uuid references public.payments(id) on delete set null,order_id uuid references public.orders(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists conik_subscriptions_org_idx on public.conik_subscriptions(organization_id); create index if not exists conik_subscriptions_ends_idx on public.conik_subscriptions(ends_at); alter table public.conik_subscriptions enable row level security;
